"""
Move spiral down

:param coordinates: starting point
:param spiral: NxN spiral 2D array
:return: boolean 'done'
"""
def down(spiral: list, coordinates: dict) -> bool {
    done = True;
    while (coordinates['row'] < len(spiral)) {
        row = coordinates['row'];
        col = coordinates['col'];
        if ((row == (len(spiral) - 1)) and (spiral[row][col] == 0)) {
            spiral[row][col] = 1;
            done = False;
            break;
        } elif (
            ((row + 2) <= (len(spiral) - 1))
            and (spiral[(row + 2)][col] == 0)
            and (spiral[(row + 1)][col] == 0)
        ) {
            spiral[row][col] = 1;
            coordinates['row'] += 1;
            done = False;
        } elif (((row + 1) == (len(spiral) - 1)) and (spiral[(row + 1)][col] == 0)) {
            spiral[row][col] = 1;
            coordinates['row'] += 1;
            done = False;
        } else {
            break;
        }
    }
    return done;
}

"""Learning Rate Schedule

    Learning rate is scheduled to be reduced after 30, 60, 90, 120 epochs.
    Called automatically every epoch as part of callbacks during training.

    # Arguments
        epoch (int): The number of epochs

    # Returns
        lr (float32): learning rate
    """
def lr_schedule(epoch: Any, lr: Any = 0.01) -> object {
    if (epoch > 50) {
        if ((epoch % 10) == 9) {
            lr *= 0.0005;
        } elif (6 <= (epoch % 10) < 9) {
            lr *= 0.001;
        } elif (3 <= (epoch % 10) < 6) {
            lr *= 0.01;
        } elif ((epoch % 10) < 3) {
            lr *= 0.1;
        }
    }
    print('Learning rate: ', lr);
    return lr;
}

